(515502, 50687, 8682, '<td valign="top">Perhaps, it´s too blurry</td>', 'Perhaps, it´s too blurry', '2003-12-17 10:16:12.000000', NULL, 1),
(515505, 50478, 13759, '<td valign="top">Interresting, consider to use the softfocus to do it.</td>', 'Interresting, consider to use the softfocus to do it.', '2003-12-17 10:17:23.000000', NULL, 1),
(515507, 50467, 8682, '<td valign="top">Good use of the negative space. I think your photograph have a lot of potential to be a fantastic picture. But, the sky is grainy and perhaps, it was overprocessing. But, just my opinion.</td>', 'Good use of the negative space. I think your photograph have a lot of potential to be a fantastic picture. But, the sky is grainy and perhaps, it was overprocessing. But, just my opinion.', '2003-12-17 10:19:20.000000', NULL, 1),
(515508, 50573, 13759, '<td valign="top">Great car! I like the oldies. I saw a little overexposured areas in your shot, on the right side of motor cover and top areas of red and white cars.</td>', 'Great car! I like the oldies. I saw a little overexposured areas in your shot, on the right side of motor cover and top areas of red and white cars.', '2003-12-17 10:19:46.000000', NULL, 1),
(515510, 50945, 13759, '<td valign="top">What about the vehicle itself?</td>', 'What about the vehicle itself?', '2003-12-17 10:20:14.000000', NULL, 1),
