(515515, 50939, 8682, '<td valign="top">Good picture. I like the plane with the sunset in the background. In my opinion, the only thing that perhaps damages your photograph is the building and the planes of the left side. But, it´s just my opinion. 7</td>', 'Good picture. I like the plane with the sunset in the background. In my opinion, the only thing that perhaps damages your photograph is the building and the planes of the left side. But, it´s just my opinion. 7', '2003-12-17 10:23:35.000000', NULL, 1),
(515516, 51201, 772, '<td valign="top">The photo doesn''t say anything to me about vehicles.  Without the title, the concept of ''vehicle'' is not present for me in any way.</td>', 'The photo doesn''t say anything to me about vehicles.  Without the title, the concept of ''vehicle'' is not present for me in any way.', '2003-12-17 10:23:43.000000', NULL, 1),
