INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(515534, 51084, 8682, '<td valign="top">Fantastic! I love this picture. Really, meets the challenge. I love the colours of your picture, I think duotone was a brilliant choice. The composition is great, too. Good use of the rule of the thirds. Definitely, one of the best pictures of this week and one of my favs. Congrats for a good work. 10</td>', 'Fantastic! I love this picture. Really, meets the challenge. I love the colours of your picture, I think duotone was a brilliant choice. The composition is great, too. Good use of the rule of the thirds. Definitely, one of the best pictures of this week and one of my favs. Congrats for a good work. 10', '2003-12-17 10:33:55.000000', NULL, 1),
(515535, 51082, 772, '<td valign="top">I put my money on the thud :)</td>', 'I put my money on the thud :)', '2003-12-17 10:34:10.000000', NULL, 1),
(515536, 51093, 13136, '<td valign="top">Transporting the mind? Personally, I think it''s a streatch for this challenge. Composition is nice.</td>', 'Transporting the mind? Personally, I think it''s a streatch for this challenge. Composition is nice.', '2003-12-17 10:34:20.000000', NULL, 1),
(515538, 51058, 8682, '<td valign="top">Really, a beatiful image. Perhaps, I´d prefer to see the image closer. 7</td>', 'Really, a beatiful image. Perhaps, I´d prefer to see the image closer. 7', '2003-12-17 10:35:19.000000', NULL, 1),
(515540, 51050, 327, '<td valign="top">Not a bad shot. The dof is pretty shallow and I think this would of benifited with a deeper dof. The bumper is a bit lost in the dark and might of been left out of the shot. Still the color is very good along with the perspective. I like that.</td>', 'Not a bad shot. The dof is pretty shallow and I think this would of benifited with a deeper dof. The bumper is a bit lost in the dark and might of been left out of the shot. Still the color is very good along with the perspective. I like that.', '2003-12-17 10:36:04.000000', NULL, 1),
(515541, 50697, 13136, '<td valign="top">Could have used better focus. Maybe show more of the inside length of train. Train should be main subject, not pretty lady.</td>', 'Could have used better focus. Maybe show more of the inside length of train. Train should be main subject, not pretty lady.', '2003-12-17 10:37:17.000000', NULL, 1),
(515543, 51201, 13136, '<td valign="top">Stretching it a bit? Nice enough shot.</td>', 'Stretching it a bit? Nice enough shot.', '2003-12-17 10:38:19.000000', NULL, 1),
