(515893, 50882, 327, '<td valign="top">Fantastic composition and colors. Lunar flight, so cool.</td>', 'Fantastic composition and colors. Lunar flight, so cool.', '2003-12-17 15:37:20.000000', NULL, 1),
(515896, 50995, 327, '<td valign="top">I''m not too crazy about the composition. The light on the white horse is a bit harsh. I do like the subject but feel they could of been presented much better. You focusing is very nice. Good luck.</td>', 'I''m not too crazy about the composition. The light on the white horse is a bit harsh. I do like the subject but feel they could of been presented much better. You focusing is very nice. Good luck.', '2003-12-17 15:38:47.000000', NULL, 1),
(515897, 50665, 327, '<td valign="top">lol the new commuter car? Neat job but I find the grass a bit unreal in color.</td>', 'lol the new commuter car? Neat job but I find the grass a bit unreal in color.', '2003-12-17 15:39:36.000000', NULL, 1),
(515900, 51062, 327, '<td valign="top">HoHoHo. A bag full of digital cameras and lenses. :) Good idea for the challenge. Maybe try to get a sharper focus.</td>', 'HoHoHo. A bag full of digital cameras and lenses. :) Good idea for the challenge. Maybe try to get a sharper focus.', '2003-12-17 15:41:16.000000', NULL, 1),
(515901, 51095, 327, '<td valign="top">I like everything here except for the door frame (left) and the shadow (right). Your composition is otherwise very interesting and clever.</td>', 'I like everything here except for the door frame (left) and the shadow (right). Your composition is otherwise very interesting and clever.', '2003-12-17 15:42:19.000000', NULL, 1),
(515903, 51087, 327, '<td valign="top">Nice focus, light and color.</td>', 'Nice focus, light and color.', '2003-12-17 15:43:22.000000', NULL, 1),
