(515906, 51072, 327, '<td valign="top">Cool shot, I love the Mini. The reflection seems very blurred or distorted. &lt;?&gt; For a mirror shot to work it needs to be crystal clear. Good color and light.</td>', 'Cool shot, I love the Mini. The reflection seems very blurred or distorted. <?> For a mirror shot to work it needs to be crystal clear. Good color and light.', '2003-12-17 15:45:54.000000', NULL, 1),
(515907, 51081, 327, '<td valign="top">Hard and expensive. AAA. Clever shot and I hope you got your car fixed. Good colors.</td>', 'Hard and expensive. AAA. Clever shot and I hope you got your car fixed. Good colors.', '2003-12-17 15:46:39.000000', NULL, 1),
(515910, 51080, 327, '<td valign="top">Pretty shot, good blue and designs.</td>', 'Pretty shot, good blue and designs.', '2003-12-17 15:48:11.000000', NULL, 1),
(515911, 51175, 12922, '<td valign="top">The reflection in the window is too distracting, would''ve been much cleaner if you put the window down.  Understandable if it''s someone else''s car though!</td>', 'The reflection in the window is too distracting, would''ve been much cleaner if you put the window down.  Understandable if it''s someone else''s car though!', '2003-12-17 15:48:15.000000', NULL, 1),
(515912, 50943, 327, '<td valign="top">Nice DOF and colors. I like this and hope you do well. I would only of liked it better if the boat was off center some. Good luck.</td>', 'Nice DOF and colors. I like this and hope you do well. I would only of liked it better if the boat was off center some. Good luck.', '2003-12-17 15:49:18.000000', NULL, 1),
(515913, 51098, 327, '<td valign="top">Good shooting, interesting capture and good color.</td>', 'Good shooting, interesting capture and good color.', '2003-12-17 15:50:19.000000', NULL, 1),
(515914, 50750, 327, '<td valign="top">LOL this is very humorous!!!!!!! Love your idea.</td>', 'LOL this is very humorous!!!!!!! Love your idea.', '2003-12-17 15:51:51.000000', NULL, 1),
(515916, 51052, 11096, '<td valign="top">Too dark to distinguish details but good composition.</td>', 'Too dark to distinguish details but good composition.', '2003-12-17 15:53:59.000000', NULL, 1),
(515918, 50749, 327, '<td valign="top">Sweeties. The driver is so serious. lol Great. Love the color, focus and causal feel of this. Hopefully next time you can catch them with a more controlled background. The car is a little distracting.</td>', 'Sweeties. The driver is so serious. lol Great. Love the color, focus and causal feel of this. Hopefully next time you can catch them with a more controlled background. The car is a little distracting.', '2003-12-17 15:54:50.000000', NULL, 1),
(515920, 51039, 327, '<td valign="top">Beautiful, stunning shot. The birds are just key to the over all feeling of length and depth. Nice tones. Good shooting.</td>', 'Beautiful, stunning shot. The birds are just key to the over all feeling of length and depth. Nice tones. Good shooting.', '2003-12-17 15:56:12.000000', NULL, 1),
(515922, 51048, 327, '<td valign="top">98% for focus, very nice. Also the colors are good. The composition is the weakness. The busy brick with the design of the board are too busy for me. I hope you do well in the challenge.</td>', '98% for focus, very nice. Also the colors are good. The composition is the weakness. The busy brick with the design of the board are too busy for me. I hope you do well in the challenge.', '2003-12-17 15:58:16.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(515924, 50976, 327, '<td valign="top">Neat shot. I do find it a bit pale/light or washed out. Still this is interesting and do like the crop and focus. Good luck in the challenge.</td>', 'Neat shot. I do find it a bit pale/light or washed out. Still this is interesting and do like the crop and focus. Good luck in the challenge.', '2003-12-17 15:59:40.000000', NULL, 1),
(515925, 51032, 13136, '<td valign="top">Been there, done that. Nice shot. Better than any I''ve taken of that train.<br/> <br/>//www.snopes.com/business/names/wgasa.asp</td>', 'Been there, done that. Nice shot. Better than any I''ve taken of that train. //www.snopes.com/business/names/wgasa.asp', '2003-12-17 16:00:14.000000', NULL, 1),
(515927, 50413, 327, '<td valign="top">Is it summer there?  This is a very good setting to shot the TT. Complimentary to the car. [even if I hate the name, I like the car] Nice going. The shot is a little small, but I''m guessing it''s the size your camera shoots. Over all good light, focus and the colors are nice.</td>', 'Is it summer there?  This is a very good setting to shot the TT. Complimentary to the car. [even if I hate the name, I like the car] Nice going. The shot is a little small, but I''m guessing it''s the size your camera shoots. Over all good light, focus and the colors are nice.', '2003-12-17 16:02:22.000000', NULL, 1),
(515928, 51060, 327, '<td valign="top">Just would of liked to see the bottom cropped a bit more. White flashing on the lower left is a bother. I love this idea and I hold Cisco stock. LOL  Good luck in the challenge.</td>', 'Just would of liked to see the bottom cropped a bit more. White flashing on the lower left is a bother. I love this idea and I hold Cisco stock. LOL  Good luck in the challenge.', '2003-12-17 16:03:42.000000', NULL, 1),
(515935, 50612, 327, '<td valign="top">Wonderful composition. Really nice. Ducati red? I''ll have to stick with my big, slower Harley. I''d kill myself with that much speed. lol Nice shot, love the whole thing and admire your creative set up. Good luck in the challenge and keep the rubber side down.</td>', 'Wonderful composition. Really nice. Ducati red? I''ll have to stick with my big, slower Harley. I''d kill myself with that much speed. lol Nice shot, love the whole thing and admire your creative set up. Good luck in the challenge and keep the rubber side down.', '2003-12-17 16:08:00.000000', NULL, 1),
(515937, 51017, 327, '<td valign="top">I love the color and the light is very nice. I would of liked more dof here, but this is pretty good as is.</td>', 'I love the color and the light is very nice. I would of liked more dof here, but this is pretty good as is.', '2003-12-17 16:08:49.000000', NULL, 1),
(515940, 50713, 13937, '<td valign="top">This is very nice!  A quick glance makes you think these are full scale!  Well Done.</td>', 'This is very nice!  A quick glance makes you think these are full scale!  Well Done.', '2003-12-17 16:09:28.000000', NULL, 1),
