(516350, 50612, 10818, '<td valign="top">I like the picture.  I would have liked it more without the toy.</td>', 'I like the picture.  I would have liked it more without the toy.', '2003-12-17 22:39:11.000000', NULL, 1),
(516379, 51199, 10047, '<td valign="top">The indoor lighting makes the picture too soft and the gold cloth around the tree doesn''t provide enough contrast. I might have tried cropping out more of the left to offset the train more in the frame (rule of thirds).</td>', 'The indoor lighting makes the picture too soft and the gold cloth around the tree doesn''t provide enough contrast. I might have tried cropping out more of the left to offset the train more in the frame (rule of thirds).', '2003-12-17 23:10:59.000000', NULL, 1),
(516384, 50665, 10047, '<td valign="top">The tractor stands out well and is a good subject. I might have cropped the top of the photo more. The building is too bland to include too much of it, just enough to contrast the with the tractor.</td>', 'The tractor stands out well and is a good subject. I might have cropped the top of the photo more. The building is too bland to include too much of it, just enough to contrast the with the tractor.', '2003-12-17 23:13:27.000000', NULL, 1),
(516385, 51058, 10047, '<td valign="top">Good compostion. I might have tried for a tighter crop with maybe one door to try and get closer to the bicycle. The spokes of the wheels look like they got jaggies.</td>', 'Good compostion. I might have tried for a tighter crop with maybe one door to try and get closer to the bicycle. The spokes of the wheels look like they got jaggies.', '2003-12-17 23:16:01.000000', NULL, 1),
(516392, 51201, 13169, '<td valign="top">No way this meets the challenge, even with a rather lame attempt to make it seem like it with the title.  This was about transport.</td>', 'No way this meets the challenge, even with a rather lame attempt to make it seem like it with the title.  This was about transport.', '2003-12-17 23:46:48.000000', NULL, 1),
(516393, 50945, 13169, '<td valign="top">Nice photo but nothing about it says vehicle or transport.</td>', 'Nice photo but nothing about it says vehicle or transport.', '2003-12-17 23:47:46.000000', NULL, 1),
