(516833, 51037, 5684, '<td valign="top">n o i s e</td>', 'n o i s e', '2003-12-18 12:32:49.000000', NULL, 1),
(516841, 51133, 12922, '<td valign="top">Did you use a flash for this shot?  It seems odd that the street signs are so bright--almost out of place.  Great shot otherwise though, I like the color tone.</td>', 'Did you use a flash for this shot?  It seems odd that the street signs are so bright--almost out of place.  Great shot otherwise though, I like the color tone.', '2003-12-18 12:43:57.000000', NULL, 1),
(516842, 50464, 10705, '<td valign="top">According to the title, your focal point is the step.  This is a nice composition, but I''d like to see the step in sharp focus...this would draw the eye to the step instead of the fender.<br/></td>', 'According to the title, your focal point is the step.  This is a nice composition, but I''d like to see the step in sharp focus...this would draw the eye to the step instead of the fender.', '2003-12-18 12:44:05.000000', NULL, 1),
(516843, 50556, 10705, '<td valign="top">This is a nice photo, nice colors ... the background is a little distracting.</td>', 'This is a nice photo, nice colors ... the background is a little distracting.', '2003-12-18 12:45:27.000000', NULL, 1),
(516845, 51146, 10705, '<td valign="top">On my computer screen, this photo looks out of focus.  There''s some wonderful colors on the old van ... nice find - definitely worth going back to photograph again.  The "soft" focus just doesn''t work for me.</td>', 'On my computer screen, this photo looks out of focus.  There''s some wonderful colors on the old van ... nice find - definitely worth going back to photograph again.  The "soft" focus just doesn''t work for me.', '2003-12-18 12:49:22.000000', NULL, 1),
(516846, 51041, 10705, '<td valign="top">Too dark to see any detail (maybe my computer screen???).  I can barely make out the swirling ... nice idea, tho.</td>', 'Too dark to see any detail (maybe my computer screen???).  I can barely make out the swirling ... nice idea, tho.', '2003-12-18 12:50:55.000000', NULL, 1),
(516848, 50478, 10705, '<td valign="top">Focus is too soft.</td>', 'Focus is too soft.', '2003-12-18 12:52:44.000000', NULL, 1),
(516856, 50984, 14593, '<td valign="top">interesting different idea</td>', 'interesting different idea', '2003-12-18 13:07:50.000000', NULL, 1),
(516857, 51138, 14593, '<td valign="top">nice photo....I like the composition</td>', 'nice photo....I like the composition', '2003-12-18 13:08:22.000000', NULL, 1),
(516859, 51200, 14593, '<td valign="top">different approach.....love the angle</td>', 'different approach.....love the angle', '2003-12-18 13:11:01.000000', NULL, 1),
(516861, 51123, 14593, '<td valign="top">very different....very creative too!  I like it!</td>', 'very different....very creative too!  I like it!', '2003-12-18 13:11:47.000000', NULL, 1),
(516863, 50962, 14593, '<td valign="top">very nice photo....love the angle, and the composition</td>', 'very nice photo....love the angle, and the composition', '2003-12-18 13:13:29.000000', NULL, 1),
(516865, 50805, 347, '<td valign="top">Could have been nicer with less background clutter, and without chopping the wheels up so much (I know, hard to achieve).</td>', 'Could have been nicer with less background clutter, and without chopping the wheels up so much (I know, hard to achieve).', '2003-12-18 13:15:13.000000', NULL, 1),
(516867, 50622, 347, '<td valign="top">Nice unusual vehicle. Some common object (not a person) nearby for scale might have made this even more impressive (say, a kitty-cat)</td>', 'Nice unusual vehicle. Some common object (not a person) nearby for scale might have made this even more impressive (say, a kitty-cat)', '2003-12-18 13:17:18.000000', NULL, 1),
(516869, 51186, 347, '<td valign="top">Yes indeed ... but please, cut your toenails before doing this again!</td>', 'Yes indeed ... but please, cut your toenails before doing this again!', '2003-12-18 13:18:50.000000', NULL, 1),
(516870, 51061, 14593, '<td valign="top">nice photo...love the composition...great in black &amp; white too</td>', 'nice photo...love the composition...great in black & white too', '2003-12-18 13:19:19.000000', NULL, 1),
(516872, 51081, 2000, '<td valign="top">Interesting perspective in this shot.  There''s a bit of reflection in the window of the tow truck, but otherwise a very unique shot.</td>', 'Interesting perspective in this shot.  There''s a bit of reflection in the window of the tow truck, but otherwise a very unique shot.', '2003-12-18 13:19:54.000000', NULL, 1),
(516873, 50467, 347, '<td valign="top">Cute. It''s a shame you had to enlarge/crop the image so much, it''s really pretty grainy, and shows up colour banding and jpeg artifacts quite a lot.<br/> <br/>I like the composition and choice of subject matter, though. Mmm, hors auto-doeuvers.</td>', 'Cute. It''s a shame you had to enlarge/crop the image so much, it''s really pretty grainy, and shows up colour banding and jpeg artifacts quite a lot. I like the composition and choice of subject matter, though. Mmm, hors auto-doeuvers.', '2003-12-18 13:21:02.000000', NULL, 1),
(516874, 51097, 14593, '<td valign="top">a well traveled vechicle!  nice photograph</td>', 'a well traveled vechicle!  nice photograph', '2003-12-18 13:21:08.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(516875, 51104, 11455, '<td valign="top">ho, a black polo !<br/> <br/>and there is two "bumps" on the wing, but if repaired, could be a nice car...</td>', 'ho, a black polo ! and there is two "bumps" on the wing, but if repaired, could be a nice car...', '2003-12-18 13:23:04.000000', NULL, 1),
(516876, 51124, 347, '<td valign="top">Good, even though I''m finding the whole black-and-white-portrait photo of motionless object thing becoming a little stale.</td>', 'Good, even though I''m finding the whole black-and-white-portrait photo of motionless object thing becoming a little stale.', '2003-12-18 13:23:15.000000', NULL, 1),
(516878, 51175, 347, '<td valign="top">Cool! Nice combination of reflection and clarity.</td>', 'Cool! Nice combination of reflection and clarity.', '2003-12-18 13:26:18.000000', NULL, 1),
(516880, 50723, 347, '<td valign="top">Wow, nice. A little more foreground/background separation could improve it even more, I think.</td>', 'Wow, nice. A little more foreground/background separation could improve it even more, I think.', '2003-12-18 13:28:21.000000', NULL, 1),
(516882, 50388, 347, '<td valign="top">Those are some weird-shaped feet, but at least the toenails aren''t all scraggly like the other foot-shot.</td>', 'Those are some weird-shaped feet, but at least the toenails aren''t all scraggly like the other foot-shot.', '2003-12-18 13:28:55.000000', NULL, 1),
(516883, 50478, 347, '<td valign="top">HowBlurry?</td>', 'HowBlurry?', '2003-12-18 13:29:17.000000', NULL, 1),
(516884, 51039, 347, '<td valign="top">That''s a nice shot -- like the sky!</td>', 'That''s a nice shot -- like the sky!', '2003-12-18 13:30:43.000000', NULL, 1),
(516885, 50731, 347, '<td valign="top">Ewww... you sure have an eye for the gruesome. Nicely framed!</td>', 'Ewww... you sure have an eye for the gruesome. Nicely framed!', '2003-12-18 13:33:19.000000', NULL, 1),
(516887, 50558, 347, '<td valign="top">This is the first panning-shot I''ve seen in the challenge that works. Nice job keeping the car centered in the lens, and I like the image size.</td>', 'This is the first panning-shot I''ve seen in the challenge that works. Nice job keeping the car centered in the lens, and I like the image size.', '2003-12-18 13:35:40.000000', NULL, 1),
(516889, 50976, 347, '<td valign="top">Nice clean (hah) shot.</td>', 'Nice clean (hah) shot.', '2003-12-18 13:36:57.000000', NULL, 1),
(516892, 51106, 347, '<td valign="top">Nice!</td>', 'Nice!', '2003-12-18 13:41:55.000000', NULL, 1),
(516896, 50726, 347, '<td valign="top">It''s a shame you had to crop this so tightly -- the car looks incomplete with hints of it existing outside the wheel and spare. Perhaps a tighter focus on the wheel and spare, ignoring the hood more, would have made for a better photo, though you''d lose the lettering which is somewhat indistinct anyway.</td>', 'It''s a shame you had to crop this so tightly -- the car looks incomplete with hints of it existing outside the wheel and spare. Perhaps a tighter focus on the wheel and spare, ignoring the hood more, would have made for a better photo, though you''d lose the lettering which is somewhat indistinct anyway.', '2003-12-18 14:07:19.000000', NULL, 1),
(516897, 51137, 347, '<td valign="top">Cute</td>', 'Cute', '2003-12-18 14:08:14.000000', NULL, 1),
(516898, 50751, 347, '<td valign="top">Nice. The fuzziness of the lighting complements the kinda fuzzy, rounded shape of the van. What''s the blob in the back?</td>', 'Nice. The fuzziness of the lighting complements the kinda fuzzy, rounded shape of the van. What''s the blob in the back?', '2003-12-18 14:08:52.000000', NULL, 1),
(516899, 50999, 347, '<td valign="top">Is this a picture of a bike, or of snow? Sepia effect does not automatically a good photo make.</td>', 'Is this a picture of a bike, or of snow? Sepia effect does not automatically a good photo make.', '2003-12-18 14:09:24.000000', NULL, 1),
(516900, 51072, 347, '<td valign="top">Nice shot -- a shame about the double image in the reflection.</td>', 'Nice shot -- a shame about the double image in the reflection.', '2003-12-18 14:10:08.000000', NULL, 1),
(516901, 51172, 347, '<td valign="top">Nice ... makes me wish I had the Guzzi together ...</td>', 'Nice ... makes me wish I had the Guzzi together ...', '2003-12-18 14:11:10.000000', NULL, 1),
(516902, 51050, 347, '<td valign="top">Scary! Nice shot.</td>', 'Scary! Nice shot.', '2003-12-18 14:12:23.000000', NULL, 1),
(516918, 50961, 10785, '<td valign="top">I believe there is too much foreground shown in this image. It is very good though.</td>', 'I believe there is too much foreground shown in this image. It is very good though.', '2003-12-18 15:05:01.000000', NULL, 1),
(516920, 50995, 10785, '<td valign="top">I would have liked to have seen a better view of the brown horse. The title says two horses, but the brown horse looks like the background for the white one.<br/> <br/>Would have fit the challenge much better had they been pulling a wagon or carriage or something.</td>', 'I would have liked to have seen a better view of the brown horse. The title says two horses, but the brown horse looks like the background for the white one. Would have fit the challenge much better had they been pulling a wagon or carriage or something.', '2003-12-18 15:10:46.000000', NULL, 1),
(516931, 51030, 10785, '<td valign="top">The picture is great, but I won''t judge the title. I''ve never seen a panning car.</td>', 'The picture is great, but I won''t judge the title. I''ve never seen a panning car.', '2003-12-18 15:37:09.000000', NULL, 1),
(516935, 50379, 7364, '<td valign="top">Lufthansa!  Excellent shot!</td>', 'Lufthansa!  Excellent shot!', '2003-12-18 15:47:38.000000', NULL, 1),
