INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(519109, 51099, 6172, '<td valign="top">Snapshot</td>', 'Snapshot', '2003-12-21 16:15:02.000000', NULL, 1),
(519111, 51177, 6172, '<td valign="top">Nice action shot, but there is so little to it.  You should have shot from an angle that included some other aspect to make the photo more enjoyable.  Here''s the subject, in the middle of the photo, and that''s all there is to this shot - it needs something else.</td>', 'Nice action shot, but there is so little to it.  You should have shot from an angle that included some other aspect to make the photo more enjoyable.  Here''s the subject, in the middle of the photo, and that''s all there is to this shot - it needs something else.', '2003-12-21 16:18:21.000000', NULL, 1),
(519115, 51191, 6172, '<td valign="top">How are the dice relevant at all?  If something doesn''t add to your photo, it detracts.</td>', 'How are the dice relevant at all?  If something doesn''t add to your photo, it detracts.', '2003-12-21 16:21:06.000000', NULL, 1),
(519118, 50703, 6172, '<td valign="top">I would judge this a better wildlife photo than a "Vehicle" photo.  I see your point, but the birds make the shot, not the little boat with bird dung all over it.</td>', 'I would judge this a better wildlife photo than a "Vehicle" photo.  I see your point, but the birds make the shot, not the little boat with bird dung all over it.', '2003-12-21 16:27:01.000000', NULL, 1),
