(519124, 51199, 14593, '<td valign="top">nice creative idea....I like it!</td>', 'nice creative idea....I like it!', '2003-12-21 16:57:33.000000', NULL, 1),
(519125, 50731, 14593, '<td valign="top">rather strange, but different!  I like different!</td>', 'rather strange, but different!  I like different!', '2003-12-21 16:59:28.000000', NULL, 1),
