(519448, 51037, 9643, '<td valign="top">I appreciate the effort it probably took to make this shot.  On my screen it is quite washed out.</td>', 'I appreciate the effort it probably took to make this shot.  On my screen it is quite washed out.', '2003-12-22 00:07:03.000000', NULL, 1),
