(520264, 51151, 14614, '<td valign="top">One of my picks for a ribbon.  Well done, crisp image fills the frame.  Snow adds interest and distinguished this from the others.</td>', 'One of my picks for a ribbon.  Well done, crisp image fills the frame.  Snow adds interest and distinguished this from the others.', '2003-12-22 18:27:47.000000', NULL, 1),
(520266, 50697, 14614, '<td valign="top">My pick for one of the ribbons.  Interesting composition and colors.  Very original - no other photo has a similar theme/subject. Well done</td>', 'My pick for one of the ribbons.  Interesting composition and colors.  Very original - no other photo has a similar theme/subject. Well done', '2003-12-22 18:28:27.000000', NULL, 1),
