(520277, 50697, 5792, '<td valign="top">Nice reds in this image even if artificially enhanced. This has a mass transit feel.</td>', 'Nice reds in this image even if artificially enhanced. This has a mass transit feel.', '2003-12-22 18:36:23.000000', NULL, 1),
