(520319, 51040, 14593, '<td valign="top">nice different approach to a transportation theme....looks like a lot of water on the road too...</td>', 'nice different approach to a transportation theme....looks like a lot of water on the road too...', '2003-12-22 19:26:34.000000', NULL, 1),
