(520375, 51124, 14836, '<td valign="top">Nice sillouhette. I like the lighting and off centered composition.</td>', 'Nice sillouhette. I like the lighting and off centered composition.', '2003-12-22 20:33:58.000000', NULL, 1),
(520376, 51177, 14836, '<td valign="top">a bit out of focus but great capture.</td>', 'a bit out of focus but great capture.', '2003-12-22 20:34:30.000000', NULL, 1),
(520379, 51134, 14836, '<td valign="top">Fantastic blurring effect. Great colors. A man at work but still in his own world.</td>', 'Fantastic blurring effect. Great colors. A man at work but still in his own world.', '2003-12-22 20:35:46.000000', NULL, 1),
(520380, 51156, 14836, '<td valign="top">Nice !</td>', 'Nice !', '2003-12-22 20:36:48.000000', NULL, 1),
(520381, 51151, 14836, '<td valign="top">Great sharpness , colors and composition.</td>', 'Great sharpness , colors and composition.', '2003-12-22 20:37:48.000000', NULL, 1),
(520387, 51175, 14836, '<td valign="top">Great softness. Love the reflection and the lighting. One of my favorite.</td>', 'Great softness. Love the reflection and the lighting. One of my favorite.', '2003-12-22 20:43:10.000000', NULL, 1),
(520388, 50656, 14836, '<td valign="top">Nice car. I like how the brightness of the background almost engulfs the car.</td>', 'Nice car. I like how the brightness of the background almost engulfs the car.', '2003-12-22 20:44:07.000000', NULL, 1),
(520406, 50413, 9906, '<td valign="top">A very nice, very small image!<br/>TC</td>', 'A very nice, very small image!TC', '2003-12-22 21:07:59.000000', NULL, 1),
(520408, 51149, 11895, '<td valign="top">needs more contrast</td>', 'needs more contrast', '2003-12-22 21:08:54.000000', NULL, 1),
(520410, 50996, 9906, '<td valign="top">Nice idea, but it''s too busy.  Take away some of the elements around it and you could turn this into a very nice shot.  You also have some lighting issues.  Too dark in the tree and too dark under wagon.<br/>TC</td>', 'Nice idea, but it''s too busy.  Take away some of the elements around it and you could turn this into a very nice shot.  You also have some lighting issues.  Too dark in the tree and too dark under wagon.TC', '2003-12-22 21:10:22.000000', NULL, 1),
(520411, 51041, 9906, '<td valign="top">I think you got the wrong challenge.  Water challenge just ended...<br/>TC</td>', 'I think you got the wrong challenge.  Water challenge just ended...TC', '2003-12-22 21:10:55.000000', NULL, 1),
(520413, 51124, 9906, '<td valign="top">Wow, this is a nice image.  It has a bit of noise that either needs to be more (arty look) or less (my preference).  Also the background needs to be light seperately to make it more uniform.  Nice silhouette effect with just enough lighting to give it a touch of dimension!  And if anyone says the guy should be peddling into the shot, ignore them.  This is IMHO much more creative!<br/>TC</td>', 'Wow, this is a nice image.  It has a bit of noise that either needs to be more (arty look) or less (my preference).  Also the background needs to be light seperately to make it more uniform.  Nice silhouette effect with just enough lighting to give it a touch of dimension!  And if anyone says the guy should be peddling into the shot, ignore them.  This is IMHO much more creative!TC', '2003-12-22 21:13:26.000000', NULL, 1),
(520414, 50726, 9906, '<td valign="top">Nice job of not getting in the reflections.  I love the simple tonal theme here!  You could use just the slightest bit of fill lighting around the spare and between tire and fender.  Other than that it''s a very nice shot.<br/>TC</td>', 'Nice job of not getting in the reflections.  I love the simple tonal theme here!  You could use just the slightest bit of fill lighting around the spare and between tire and fender.  Other than that it''s a very nice shot.TC', '2003-12-22 21:15:15.000000', NULL, 1),
(520415, 51146, 9906, '<td valign="top">You have some focus issues here.  It almosts looks like you used the digital zoom.  I like the colors.<br/>TC</td>', 'You have some focus issues here.  It almosts looks like you used the digital zoom.  I like the colors.TC', '2003-12-22 21:17:29.000000', NULL, 1),
(520416, 51060, 9906, '<td valign="top">Nice set up shot.  Good DOF on the cab of the truck.  You could use a little fill flash to bring out the details in the tires.  You lose it with unneeded background elements.  The lighthouse is good, but the rest of the stuff detracts from an otherwise nice shot.<br/>TC</td>', 'Nice set up shot.  Good DOF on the cab of the truck.  You could use a little fill flash to bring out the details in the tires.  You lose it with unneeded background elements.  The lighthouse is good, but the rest of the stuff detracts from an otherwise nice shot.TC', '2003-12-22 21:19:25.000000', NULL, 1),
(520417, 50749, 9906, '<td valign="top">Beautifull colors!  Unfortunately this is one of those shots that if you don''t know the children, it really doesn''t have an impact.  Get all the vehicle in the picture, get rid of the background vehicle, get the kids looking out the front of the jeep and maybe you got a shot that won''t get dubbed a snapshot here.<br/>TC</td>', 'Beautifull colors!  Unfortunately this is one of those shots that if you don''t know the children, it really doesn''t have an impact.  Get all the vehicle in the picture, get rid of the background vehicle, get the kids looking out the front of the jeep and maybe you got a shot that won''t get dubbed a snapshot here.TC', '2003-12-22 21:22:05.000000', NULL, 1),
(520418, 51177, 9906, '<td valign="top">Nice capture!<br/>TC</td>', 'Nice capture!TC', '2003-12-22 21:22:35.000000', NULL, 1),
(520423, 51054, 9906, '<td valign="top">Nicely composed and nice pose of your model.  The tones don''t quite look right though.  You did a great job of getting the metal look of the handlebars without terrible reflections, but the girl looks too... (red maybe?)  Oh and your border is overbearing and really detracts from the image.  It''s the first thing I noticed.<br/>TC</td>', 'Nicely composed and nice pose of your model.  The tones don''t quite look right though.  You did a great job of getting the metal look of the handlebars without terrible reflections, but the girl looks too... (red maybe?)  Oh and your border is overbearing and really detracts from the image.  It''s the first thing I noticed.TC', '2003-12-22 21:25:26.000000', NULL, 1),
(520425, 51197, 9906, '<td valign="top">If you''re driving from that side of the car you''re on something.  I never have liked the overprocessed psychedelic looking shots and this is no exception...<br/>TC</td>', 'If you''re driving from that side of the car you''re on something.  I never have liked the overprocessed psychedelic looking shots and this is no exception...TC', '2003-12-22 21:26:23.000000', NULL, 1),
(520426, 50810, 9906, '<td valign="top">That looks like a lot of fun!  Nice capture.  You appear to have some issues with the yellow color on the sail though.<br/>TC</td>', 'That looks like a lot of fun!  Nice capture.  You appear to have some issues with the yellow color on the sail though.TC', '2003-12-22 21:27:08.000000', NULL, 1),
(520430, 51202, 9906, '<td valign="top">This is an excellent shot of a model!  I love the angle that you chose here.  You give the feeling of actually climbing on the bike!  The only thing I don\''t like is you lose a lot of detail because your lighting is a touch dark.  Great colorscheme.  The red &amp; black go great together and is complemented by the seat covers!<br/>Work on the lighting and this could be a perfect shot!</td>', 'This is an excellent shot of a model!  I love the angle that you chose here.  You give the feeling of actually climbing on the bike!  The only thing I don\''t like is you lose a lot of detail because your lighting is a touch dark.  Great colorscheme.  The red & black go great together and is complemented by the seat covers!Work on the lighting and this could be a perfect shot!', '2003-12-22 21:29:15.000000', NULL, 1),
(520434, 51147, 9906, '<td valign="top">Too many hot spots and looks oversharpened (maybe because you have too many hot spots).<br/>TC</td>', 'Too many hot spots and looks oversharpened (maybe because you have too many hot spots).TC', '2003-12-22 21:30:27.000000', NULL, 1),
(520443, 51094, 9906, '<td valign="top">Too small, out of focus, poorly lit, un-interesting.<br/>TC</td>', 'Too small, out of focus, poorly lit, un-interesting.TC', '2003-12-22 21:36:10.000000', NULL, 1),
(520445, 51168, 9906, '<td valign="top">And I wish I understood what you were trying to do with this picture.  I''m sorry, but I just don''t get it...<br/>TC</td>', 'And I wish I understood what you were trying to do with this picture.  I''m sorry, but I just don''t get it...TC', '2003-12-22 21:40:25.000000', NULL, 1),
(520447, 51039, 9906, '<td valign="top">Very nice use of B/W here.  You have some awesome tones that I don''t think would have worked in color.  Great capture of the stormy looking clouds.   Beatiful shot!<br/>TC</td>', 'Very nice use of B/W here.  You have some awesome tones that I don''t think would have worked in color.  Great capture of the stormy looking clouds.   Beatiful shot!TC', '2003-12-22 21:45:23.000000', NULL, 1),
(520449, 50750, 9906, '<td valign="top">Very funny!  You have some exposure issue, but never having taken a picture of an invisible car, I don''t know how to help you here.  Oh and I wanna know how you do this kind of border.<br/>TC</td>', 'Very funny!  You have some exposure issue, but never having taken a picture of an invisible car, I don''t know how to help you here.  Oh and I wanna know how you do this kind of border.TC', '2003-12-22 21:53:56.000000', NULL, 1),
(520460, 50379, 8125, '<td valign="top">I love this shot - the color, composition, lighting... excellent.  The contrast between the fog and crisp clarity of the plane really works well.  I''ll bet this is in winners row.  Excellent work!!</td>', 'I love this shot - the color, composition, lighting... excellent.  The contrast between the fog and crisp clarity of the plane really works well.  I''ll bet this is in winners row.  Excellent work!!', '2003-12-22 22:07:33.000000', NULL, 1),
(520461, 51116, 8125, '<td valign="top">This is a nice image.  I like the yellow of the bug, really makes it pop out of the picture.  Lighting, composition good...</td>', 'This is a nice image.  I like the yellow of the bug, really makes it pop out of the picture.  Lighting, composition good...', '2003-12-22 22:08:32.000000', NULL, 1),
(520462, 50622, 15306, '<td valign="top">xcvfdcvs</td>', 'xcvfdcvs', '2003-12-22 22:08:35.000000', NULL, 1),
(520466, 50612, 8125, '<td valign="top">Good idea... well executed.  Lighing and composition is good.  The red is striking.  Not sure the red in the border is needed...</td>', 'Good idea... well executed.  Lighing and composition is good.  The red is striking.  Not sure the red in the border is needed...', '2003-12-22 22:13:52.000000', NULL, 1),
(520469, 51080, 8125, '<td valign="top">The roller coaster track looks really cool.  The track itself sillouhetted and the color of the sky actually take my attention away from the coaster cars.  I didn''t realize they were on the loop until I''d seen the picture 3 times.  The white glare also distracts my attention somewhat.  Not sure how well this fits in the ''vehicles'' challenge, but I see definately see the intent and I''m not basing my score on that.  Overall a great shot.</td>', 'The roller coaster track looks really cool.  The track itself sillouhetted and the color of the sky actually take my attention away from the coaster cars.  I didn''t realize they were on the loop until I''d seen the picture 3 times.  The white glare also distracts my attention somewhat.  Not sure how well this fits in the ''vehicles'' challenge, but I see definately see the intent and I''m not basing my score on that.  Overall a great shot.', '2003-12-22 22:19:17.000000', NULL, 1),
(520470, 51063, 8125, '<td valign="top">Your lighting is a bit off and this seems a little out of focus.  Real feet probably would have scored higher.  Sorry...</td>', 'Your lighting is a bit off and this seems a little out of focus.  Real feet probably would have scored higher.  Sorry...', '2003-12-22 22:21:29.000000', NULL, 1),
(520472, 50751, 8125, '<td valign="top">Your light is too harsh.  Seems a little out of focus.  What is in the back of that truck?</td>', 'Your light is too harsh.  Seems a little out of focus.  What is in the back of that truck?', '2003-12-22 22:22:41.000000', NULL, 1),
(520474, 51166, 8125, '<td valign="top">This seems more of a tool than a mode of transportation.  However, it technically is a vehicle.  A well taken picture.  I like the reflection in the smooth ice.</td>', 'This seems more of a tool than a mode of transportation.  However, it technically is a vehicle.  A well taken picture.  I like the reflection in the smooth ice.', '2003-12-22 22:25:16.000000', NULL, 1),
(520476, 50718, 8125, '<td valign="top">I would have liked to see less of the top and more of the bottom.  Also, your subject looks new, so the b&amp;w doesn''t seem to fit the image.  However, I do like it.  I am, though, left wondering what great color there probably was in this shot.  Overall, a good image.</td>', 'I would have liked to see less of the top and more of the bottom.  Also, your subject looks new, so the b&w doesn''t seem to fit the image.  However, I do like it.  I am, though, left wondering what great color there probably was in this shot.  Overall, a good image.', '2003-12-22 22:27:23.000000', NULL, 1),
(520479, 50474, 8125, '<td valign="top">I''m sorry - I don''t see this fitting a ''vehicle'' challenge.  I do see your intent as the girl in front is on top of, so giving the effect of ''riding''.  <br/> <br/>Technical comments:  Composition is good, lighting seems good even though you were shooting in the shade with sun in the background.  I might have zoomed in a bit more to really capture the expressions of the girls.</td>', 'I''m sorry - I don''t see this fitting a ''vehicle'' challenge.  I do see your intent as the girl in front is on top of, so giving the effect of ''riding''.   Technical comments:  Composition is good, lighting seems good even though you were shooting in the shade with sun in the background.  I might have zoomed in a bit more to really capture the expressions of the girls.', '2003-12-22 22:30:19.000000', NULL, 1),
(520486, 50858, 8125, '<td valign="top">Definately fitting of the challenge.  Your sky seems to have some noise.  There isn''t a lot of color opportunity in this shot, but the whites and blacks seem a little dull.</td>', 'Definately fitting of the challenge.  Your sky seems to have some noise.  There isn''t a lot of color opportunity in this shot, but the whites and blacks seem a little dull.', '2003-12-22 22:34:51.000000', NULL, 1),
(520487, 51072, 8125, '<td valign="top">I like the reflection and I like the red.  Lighting seems good...  nice work.  :-)</td>', 'I like the reflection and I like the red.  Lighting seems good...  nice work.  :-)', '2003-12-22 22:36:04.000000', NULL, 1),
(520489, 51151, 8125, '<td valign="top">I really like this shot.  Love how the color of the truck really contrasts with the snow.  Compositionally, it seems ever so slightly tilted to the right... but now I''m picking.  Great idea, well done!!  :-)</td>', 'I really like this shot.  Love how the color of the truck really contrasts with the snow.  Compositionally, it seems ever so slightly tilted to the right... but now I''m picking.  Great idea, well done!!  :-)', '2003-12-22 22:37:48.000000', NULL, 1),
(520490, 51007, 8125, '<td valign="top">This is a pretty emotive shot... dark gloomy day, frustrations of traffic... I''m feelin'' it  :-) <br/></td>', 'This is a pretty emotive shot... dark gloomy day, frustrations of traffic... I''m feelin'' it  :-) ', '2003-12-22 22:39:07.000000', NULL, 1),
(520517, 51041, 8125, '<td valign="top">This seems better applied to the water challenge.  What type of ''vehicle'' are you trying to portray?</td>', 'This seems better applied to the water challenge.  What type of ''vehicle'' are you trying to portray?', '2003-12-22 23:24:31.000000', NULL, 1),
(520522, 50838, 8125, '<td valign="top">This reminds of the tv show ''Dawsons Creek''.  An excellent subject and I like the reflection in the water.  Lighting is a bit dark, and there is a lot of noise in the image.</td>', 'This reminds of the tv show ''Dawsons Creek''.  An excellent subject and I like the reflection in the water.  Lighting is a bit dark, and there is a lot of noise in the image.', '2003-12-22 23:25:49.000000', NULL, 1),
(520526, 51130, 8125, '<td valign="top">I would suggest cropping a bit more off the bottom - otherwise a great shot!  Lighting and composition are very good.  A nice match to this challenge topic.  Well done!</td>', 'I would suggest cropping a bit more off the bottom - otherwise a great shot!  Lighting and composition are very good.  A nice match to this challenge topic.  Well done!', '2003-12-22 23:27:14.000000', NULL, 1),
(520530, 50875, 8125, '<td valign="top">I really like this shot - Excellent capture.</td>', 'I really like this shot - Excellent capture.', '2003-12-22 23:28:17.000000', NULL, 1),
(520532, 50687, 8125, '<td valign="top">Way out of focus...</td>', 'Way out of focus...', '2003-12-22 23:28:42.000000', NULL, 1),
(520535, 51094, 8125, '<td valign="top">I''m sorry... but I just have to comment and I hope this helps you for future challenges.  The image is too small, way out of focus and I''m not sure how this applies as a ''vehicle''.  It appears you may have too much lighting in the lower left edge of the shot.</td>', 'I''m sorry... but I just have to comment and I hope this helps you for future challenges.  The image is too small, way out of focus and I''m not sure how this applies as a ''vehicle''.  It appears you may have too much lighting in the lower left edge of the shot.', '2003-12-22 23:34:58.000000', NULL, 1),
(520536, 50810, 8125, '<td valign="top">Excellent color contrasts.  Composition and lighting are good.  Definate interest... nice shot and fitting for the challenge.  Great work.  :-)<br/></td>', 'Excellent color contrasts.  Composition and lighting are good.  Definate interest... nice shot and fitting for the challenge.  Great work.  :-)', '2003-12-22 23:36:21.000000', NULL, 1),
(520540, 51180, 12268, '<td valign="top">This is a great shot, I give it an 8. It does, however, seem a bit over exposed and the crop is too tight on the left corner.</td>', 'This is a great shot, I give it an 8. It does, however, seem a bit over exposed and the crop is too tight on the left corner.', '2003-12-22 23:49:01.000000', NULL, 1),
(520541, 50693, 12268, '<td valign="top">great original shot idea! I love it. 8. It does seem a tad dark though.</td>', 'great original shot idea! I love it. 8. It does seem a tad dark though.', '2003-12-22 23:49:33.000000', NULL, 1),
(520542, 50676, 12268, '<td valign="top">too bad it''s dead. It''s a great truck with a lot of character. Excellent shot. 8</td>', 'too bad it''s dead. It''s a great truck with a lot of character. Excellent shot. 8', '2003-12-22 23:50:10.000000', NULL, 1),
(520551, 51145, 10818, '<td valign="top">Pretty bike.  I love the blue.  Photo is not as pretty as the bike though.<br/> <br/></td>', 'Pretty bike.  I love the blue.  Photo is not as pretty as the bike though. ', '2003-12-23 00:07:43.000000', NULL, 1),
(520560, 51084, 9643, '<td valign="top">I really like the composition in this photo as well as the color tone and detail.  Nice 9</td>', 'I really like the composition in this photo as well as the color tone and detail.  Nice 9', '2003-12-23 00:43:19.000000', NULL, 1),
(520563, 51086, 9643, '<td valign="top">Really interesting light and color in this photo</td>', 'Really interesting light and color in this photo', '2003-12-23 00:48:48.000000', NULL, 1),
(520584, 50750, 15199, '<td valign="top">Great concept, pity one could not judge originality which your picture had loads of. Pity on the black marks on the snow. I would have preferred a clean prestine white with the wheels forming the contrast, yet its a matter of personal preference.</td>', 'Great concept, pity one could not judge originality which your picture had loads of. Pity on the black marks on the snow. I would have preferred a clean prestine white with the wheels forming the contrast, yet its a matter of personal preference.', '2003-12-23 02:52:13.000000', NULL, 1),
(520586, 50711, 15199, '<td valign="top">I like the textured feel of the picture. I think the wheel dominates the picture, distracting a bit from the overall feel of the subject.</td>', 'I like the textured feel of the picture. I think the wheel dominates the picture, distracting a bit from the overall feel of the subject.', '2003-12-23 02:56:30.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(520587, 51041, 15199, '<td valign="top">Very original interpretation of vehicles. Pity on the lack of clarity of the picture and the missing border on the bottom left to give it symmetry. Top marks for originality though.</td>', 'Very original interpretation of vehicles. Pity on the lack of clarity of the picture and the missing border on the bottom left to give it symmetry. Top marks for originality though.', '2003-12-23 02:57:03.000000', NULL, 1),
(520591, 51205, 15199, '<td valign="top">I really like the interplay of the different vehicles within this picture. The only drawback is the line cutting the picture in half which is discontinued at the bottom. Maybe a crop to remove the bottom bars might have worked better.</td>', 'I really like the interplay of the different vehicles within this picture. The only drawback is the line cutting the picture in half which is discontinued at the bottom. Maybe a crop to remove the bottom bars might have worked better.', '2003-12-23 02:59:57.000000', NULL, 1),
(520592, 50697, 15199, '<td valign="top">Very interesting play of colour, motion and the apparent lifelessness of the subject. Great composition.</td>', 'Very interesting play of colour, motion and the apparent lifelessness of the subject. Great composition.', '2003-12-23 03:00:24.000000', NULL, 1),
(520594, 51095, 15199, '<td valign="top">I really like the unusual geometry of the picture. Pity on the doorway (or what looks like it) in quite strong focus in the background.</td>', 'I really like the unusual geometry of the picture. Pity on the doorway (or what looks like it) in quite strong focus in the background.', '2003-12-23 03:07:01.000000', NULL, 1),
